using System;

namespace mailTester.Mail
{
    public static class DiagnosticAdvice
    {
        public static string For(CheckFinding f, string domain = null)
        {
            string summary=f.Summary ?? "", detail=f.Detail ?? "";
            bool Has(string text)=>summary.Contains(text,StringComparison.OrdinalIgnoreCase)||detail.Contains(text,StringComparison.OrdinalIgnoreCase);
            if (f.Level==CheckLevel.Unknown)
                return "Проверка не завершена. Проверьте указанный резолвер/соединение и повторите запрос. Не меняйте DNS-политику только на основании этого результата.";
            if (f.Level==CheckLevel.Skipped)
                return f.Section=="DKIM"?"Укажите селектор s= и домен d= из DKIM-Signature реального письма. Отсутствие проверки не означает отсутствие DKIM." :
                    f.Section=="PTR"?"Получите адрес сервера и запустите PTR отдельно." : "Уточните исходные данные и повторите именно эту проверку.";
            if(f.Section=="DMARC" && Has("pct: historic"))
                return "Сохраните существующие rua/ruf и политику, если они нужны; удалите устаревший pct после проверки отчётов и готовности к полной политике. t=y не эквивалент pct=70. Не ослабляйте quarantine до none автоматически. Для внешних rua/ruf проверьте разрешение получателя; после анализа alignment рассмотрите p=reject.";
            if(f.Section=="TLS" && Has("внутренний CA"))
                return "Сертификат доверен на данном ПК, но внешний клиент может не доверять корпоративному CA. Проверьте с внешней машины без корпоративного корня. Если это публичная служба, рассмотрите сертификат общеизвестного CA. Не заменяйте внутренний CA автоматически.";
            if(f.Level==CheckLevel.Ok)
                return f.Section=="SPF" && Has("статическая") ? "Запись опубликована; отдельно проверьте реальные SMTP IP, MAIL FROM и HELO. -all не означает SPF PASS для любого письма." :
                    f.Section=="TLS" || f.Section=="WHOIS" || f.Section=="RDAP" ? "Срочных действий по этой проверке нет. Контролируйте срок и автопродление." :
                    f.Section=="DNS" && Has("системное разрешение") ? "Сравните с выбранным резолвером; системное разрешение не заменяет его DNS-ответ." : "По этой проверке исправления не требуются; контролируйте изменения.";
            if(f.Level==CheckLevel.Info)
                return f.Section=="DNSBL" ? "Проверяйте именно исходящий публичный SMTP IP; MX может быть только принимающим сервером." :
                    f.Section=="DNS" ? "Информационная запись; отсутствие необязательных типов или служебных имён само по себе не ошибка." : "Информационный результат; изменений может не требоваться.";
            switch(f.Section)
            {
                case "DMARC":
                    return Has("не обнаружена") ? "Настройте SPF/DKIM и опубликуйте TXT _dmarc: v=DMARC1; p=none; rua=mailto:<реальный ящик>. После анализа отчётов переходите quarantine/reject." :
                        "Проверьте выравнивание SPF/DKIM и существующую политику, отчёты rua/ruf. RFC 9989: pct устарел; t=y запрашивает тестовый режим (reject→quarantine, quarantine→none); не меняйте p без анализа.";
                case "SPF": return "Проверьте все реальные отправляющие IP и провайдеров. Одна TXT v=spf1; исправьте дубликаты, +all, лишние include и ошибки CIDR; тестируйте конкретные SMTP IP.";
                case "DKIM": return "Проверьте d=/s=, опубликуйте выданный вашим MTA публичный ключ, RSA 2048 либо поддерживаемый Ed25519. Не публикуйте закрытый ключ.";
                case "MX": return "Проверьте MX и его A/AAAA. MX не должен указывать на CNAME; Null MX подходит только для домена без входящей почты.";
                case "PTR": return "Сверьте PTR с прямым A/AAAA и EHLO исходящего сервера; PTR меняется у владельца IP.";
                case "DNSBL": return "Проверьте код ответа и правила конкретного списка. При реальном LISTED устраните причину до delisting; PBL не обязательно означает спам.";
                case "TLS": return "Проверьте срок, имя/SAN, часы, цепочку доверия и SNI. При истечении продлите сертификат и установите цепочку; при ошибке подключения проверьте порт и режим.";
                case "RDAP": case "WHOIS": return "Сверьте paid-till/expiration и статус в кабинете регистратора. Включите автопродление; сведения реестра не подтверждают оплату счёта.";
                default: return "Проверьте конкретную запись, ответ резолвера и конфигурацию службы.";
            }
        }
    }
}
